 			}
 			return args[index], nil
 		}
 		var err error
 		switch arg {
 		case "--repo":
 			flags.Repo, err = value()
 		case "--setup":
 			flags.Setup, err = value()
 		case "--test":
 			flags.Test, err = value()
 		case "--pre-edit-baseline":
 			flags.PreEditBaseline, err = value()
 		case "--record-baseline":
 			flags.RecordBaseline, err = value()
 		case "--max-bytes":
