func validateSet(set *Set) error {
	ids := map[string]bool{}
	anchors := map[string]bool{}
	acceptances := map[string]bool{}
	tests := map[string]bool{}
	decisions := map[string]bool{}
	for _, s := range set.Specs {
		if ids[s.ID] {
			return fmt.Errorf("duplicate specification id %q", s.ID)
		}
		ids[s.ID] = true
		for _, acceptance := range s.Acceptance {
			if acceptances[acceptance.ID] {
				return fmt.Errorf("duplicate acceptance id %q", acceptance.ID)
			}
			acceptances[acceptance.ID] = true
		}
		for _, test := range s.Tests {
			if tests[test.ID] {
				return fmt.Errorf("duplicate test id %q", test.ID)
			}
			tests[test.ID] = true
		}
		for _, a := range s.Anchors {
			if anchors[a.ID] {
				return fmt.Errorf("duplicate anchor id %q", a.ID)
			}
			anchors[a.ID] = true
		}
	}
	for _, decision := range set.Decisions {
		if decisions[decision.ID] {
			return fmt.Errorf("duplicate decision id %q", decision.ID)
		}
		decisions[decision.ID] = true
		for _, spec := range decision.Affects {
			if !ids[spec] {
				return fmt.Errorf("decision %q affects unknown specification %q", decision.ID, spec)
			}
		}
		for _, anchor := range decision.Anchors {
			if !anchors[anchor] {
				return fmt.Errorf("decision %q references unknown anchor %q", decision.ID, anchor)
			}
		}
	}
	for _, spec := range set.Specs {
		for _, relationship := range spec.Relationships {
			if !ids[relationship.Target] {
				return fmt.Errorf("specification %q references unknown relationship target %q", spec.ID, relationship.Target)
			}
		}
	}
	seen := map[string]bool{}
	for _, b := range set.Bindings {
		if !anchors[b.ID] {
			return fmt.Errorf("binding %q is not declared", b.ID)
		}
		if seen[b.ID] {
			return fmt.Errorf("duplicate binding %q", b.ID)
		}
		seen[b.ID] = true
	}
	return nil
}
func decodeFile(path string, dest any) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()
	data, err := io.ReadAll(io.LimitReader(f, maxDocumentBytes+1))
	if err != nil {
		return err
	}
	if len(data) > maxDocumentBytes {
		return fmt.Errorf("YAML document exceeds %d byte limit", maxDocumentBytes)
	}
	var document yaml.Node
	if err := yaml.Unmarshal(data, &document); err != nil {
		return err
	}
	if containsAlias(&document) {
		return errors.New("YAML aliases are not supported")
	}
	d := yaml.NewDecoder(bytes.NewReader(data))
	d.KnownFields(true)
	if err := d.Decode(dest); err != nil {
		return err
	}
	var extra any
	if err := d.Decode(&extra); err != io.EOF {
		return errors.New("YAML document must contain one document")
	}
	return nil
}

func containsAlias(node *yaml.Node) bool {
	if node.Kind == yaml.AliasNode {
		return true
	}
	for _, child := range node.Content {
		if containsAlias(child) {
			return true
		}
	}
	return false
}
func loadYAMLFiles(root string, fn func(string) error) error {
	var paths []string
	err := filepath.WalkDir(root, func(path string, entry os.DirEntry, walkErr error) error {
		if errors.Is(walkErr, os.ErrNotExist) && path == root {
			return nil
		}
		if walkErr != nil {
			return walkErr
		}
		if entry.Type()&os.ModeSymlink != 0 {
			if entry.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if entry.IsDir() {
			return nil
		}
		ext := strings.ToLower(filepath.Ext(entry.Name()))
		if ext == ".yaml" || ext == ".yml" {
			paths = append(paths, path)
		}
		return nil
	})
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	sort.Strings(paths)
	for _, p := range paths {
		if err := fn(p); err != nil {
			return err
		}
	}
	return nil
}
func writeYAML(path string, value any) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	data, err := yaml.Marshal(value)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0o644)
}
func safeRelative(path string) bool {
	return path != "" && !filepath.IsAbs(path) && !strings.Contains(filepath.ToSlash(filepath.Clean(path)), "../") && filepath.Clean(path) != ".."
}
func rel(repo, path string) string {
	value, err := filepath.Rel(repo, path)
	if err != nil {
		return path
	}
	return filepath.ToSlash(value)
}
func digest(data []byte) string {
	sum := sha256.Sum256(data)
	return "sha256:" + hex.EncodeToString(sum[:])
}

package intent

import (
	"os"
	"path/filepath"
	"testing"
)

func TestLoadValidatesReferencesAndBindings(t *testing.T) {
	repo := t.TempDir()
	if err := Init(repo); err != nil {
		t.Fatal(err)
	}
	spec := `version: 1
id: SPEC-1
title: Authentication
requirements:
  - id: REQ-1
    description: A user receives a token.
acceptance:
  - id: ACC-1
    requirement: REQ-1
    description: A token is returned.
anchors:
  - id: ANCHOR-1
    requirement: REQ-1
tests:
  - id: TEST-1
    acceptance: ACC-1
    selector:
      name: TestToken
`
	if err := os.WriteFile(filepath.Join(repo, Root, "specs", "auth.yaml"), []byte(spec), 0o644); err != nil {
		t.Fatal(err)
	}
	set, err := Load(repo)
	if err != nil {
		t.Fatal(err)
	}
	if len(set.Specs) != 1 || set.Digest == "" {
		t.Fatalf("unexpected intent set: %+v", set)
	}
	if err := SaveBinding(repo, Binding{ID: "UNKNOWN", SymbolID: "symbol"}, false); err == nil {
		t.Fatal("accepted undeclared binding")
	}
}

func TestLoadRejectsYAMLAliases(t *testing.T) {
	repo := t.TempDir()
	if err := Init(repo); err != nil {
		t.Fatal(err)
	}
	spec := "version: 1\nid: SPEC-1\ntitle: Authentication\nrequirements:\n  - &requirement\n    id: REQ-1\n    description: A user authenticates.\n  - *requirement\n"
	if err := os.WriteFile(filepath.Join(repo, Root, "specs", "auth.yaml"), []byte(spec), 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := Load(repo); err == nil {
		t.Fatal("accepted YAML alias")
	}
}

